function creerEventEmitter() {
  const evenements = {};

  return {
    on(event, fn) {
      if (!evenements[event]) {
        evenements[event] = [];
      }
      evenements[event].push(fn);
    },
    off(event, fn) {
      if (evenements[event]) {
        evenements[event] = evenements[event].filter(f => f !== fn);
      }
    },
    emit(event, ...args) {
      if (evenements[event]) {
        evenements[event].forEach(fn => fn(...args));
      }
    }
  };
}
