  let failures = 0;
  let state = 'CLOSED';
  let resetTimer = null;

  return async function(...args) {
    if (state === 'OPEN') {
      if (Date.now() >= resetTimer) {
        state = 'HALF_OPEN';
      } else {
        throw new Error('Circuit breaker is OPEN');
      }
    }

