      const result = await fn(...args);
      if (state === 'HALF_OPEN') {
        state = 'CLOSED';
        failures = 0;
      } else if (state === 'CLOSED') {
        failures = 0;
      }
      return result;
    } catch (error) {
      if (state === 'HALF_OPEN') {
        state = 'OPEN';
        resetTimer = Date.now() + delaiResetMs;
      } else {
        failures++;
        if (failures >= seuil) {
          state = 'OPEN';
          resetTimer = Date.now() + delaiResetMs;
        }
      }
      throw error;
    }
  };
}
