function dijkstra(graphe, depart) {
  const distances = {};
  const visites = new Set();
  const noeuds = new Set();

  for (const noeud in graphe) {
    noeuds.add(noeud);
    for (const voisin in graphe[noeud]) {
      noeuds.add(voisin);
    }
  }

  for (const noeud of noeuds) {
    distances[noeud] = Infinity;
  }
  distances[depart] = 0;

  while (true) {
    let noeudCourant = null;
    let minDistance = Infinity;

    for (const noeud of noeuds) {
      if (!visites.has(noeud) && distances[noeud] < minDistance) {
        minDistance = distances[noeud];
        noeudCourant = noeud;
      }
    }

    if (noeudCourant === null || minDistance === Infinity) {
      break;
    }

    visites.add(noeudCourant);

    if (graphe[noeudCourant]) {
      for (const voisin in graphe[noeudCourant]) {
        const poids = graphe[noeudCourant][voisin];
        const nouvelleDistance = distances[noeudCourant] + poids;
        if (nouvelleDistance < distances[voisin]) {
          distances[voisin] = nouvelleDistance;
