      high = partitionA - 1;
    } else {
      low = partitionA + 1;
    }
  }

  throw new Error("Les tableaux d'entrée ne sont pas triés");
}

function plusLongueSousSuiteCroissante(tab) {
  if (tab.length === 0) return 0;

  const tails = [];
  for (const x of tab) {
    let left = 0;
    let right = tails.length;

    while (left < right) {
      const mid = Math.floor((left + right) / 2);
      if (tails[mid] < x) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }

    if (left === tails.length) {
      tails.push(x);
    } else {
      tails[left] = x;
    }
  }

  return tails.length;
}
